export enum SupportedDatastores {
    s3 = 's3',
}

/**
 * The default region used for datastore based measurements when none is provided.
 */
export const DEFAULT_DATASTORE_REGION = 'us-east-1';

/**
 * The prefix used for every IAM role created for a datastore based measurement.
 */
export const DATASTORE_ROLE_PREFIX = 'datastore';

/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions
 * Specifically this is the access information needed for connectors ingesting data from a clients env.
 * There are many different connectors with different access and control needs.
 * For example a MySQL connector is not the same as a S3 Connector.
 *
 * For the `s3` platform Paigo generates a dedicated IAM role, which is only assumable by the
 * customer account (`accountId`) when the generated `externalId` is presented. That role is scoped down
 * to the ingestion and dead letter queue (DLQ) prefixes belonging to the business.
 * */
export class DatastoreAccessInformation {
    /**
     * Underlying datastore platform which paigo ingests usage data from. Optional, default is `s3`.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        example: 's3',
    })
    public platform?: SupportedDatastores;

    /**
     * The Unique ID of the cloud account which is going to deliver usage data to Paigo. Required.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '623673123435' })
    public accountId: string;

    /**
     * The IAM role generated by Paigo, which the account identified by `accountId` can assume
     * in order to deliver usage records. Generated by Paigo, read only.
     * <br><br>
     * Example `"arn:aws:iam::214826386939:role/datastore-myBusiness-de388932-a7e1-11ed-afa1-0242ac120002"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, readOnly: true })
    public iamRoleArn?: string;

    /**
     * The External ID which must be presented when assuming the generated `iamRoleArn`.
     * Generated by Paigo, read only.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, readOnly: true })
    public externalId?: string;

    /**
     * The location usage records must be delivered to. Generated by Paigo, read only.
     * <br><br>
     * Example `"s3://paigo-usage-record-dump-bucket/myBusiness"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, readOnly: true })
    public ingestion?: string;

    /**
     * The location where records that failed processing are delivered to. Generated by Paigo, read only.
     * <br><br>
     * Example `"s3://paigo-usage-record-dlq-bucket/myBusiness"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, readOnly: true })
    public dlq?: string;

    /**
     * The region of the ingestion and DLQ locations. Optional, default is `us-east-1`.
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: DEFAULT_DATASTORE_REGION })
    public region?: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID?: string;

    @ApiHideProperty()
    @IsOptional()
    public measurementId?: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation) {
        if (datastoreAccessInformation) {
            const {
                accountId,
                platform,
                iamRoleArn,
                externalId,
                ingestion,
                dlq,
                region,
                businessID,
                measurementId,
            } = datastoreAccessInformation;
            this.platform = platform ? (platform.toLowerCase() as SupportedDatastores) : SupportedDatastores.s3;
            this.accountId = accountId;
            this.region = region ? region : DEFAULT_DATASTORE_REGION;
            this.businessID = businessID;
            this.measurementId = measurementId;
            this.ingestion = ingestion
                ? ingestion
                : DatastoreAccessInformation.buildLocation(process.env.DB_MEASUREMENT_BUCKET_NAME, businessID);
            this.dlq = dlq
                ? dlq
                : DatastoreAccessInformation.buildLocation(process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME, businessID);
            if (iamRoleArn) {
                this.iamRoleArn = iamRoleArn;
            }
            if (externalId) {
                this.externalId = externalId;
            }
        }
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { platform, accountId, iamRoleArn, externalId, ingestion, dlq, region } =
                datastoreAccessInformation;
            if (platform) influxPoint.tag('platform', platform);
            if (accountId) influxPoint.tag('accountId', accountId);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
            if (region) influxPoint.tag('region', region);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        accountId,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        region,
        businessID,
        measurementId,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform,
            accountId,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            region,
            businessID,
            measurementId,
        });
    }

    /**
     * The name of the IAM role and of the policy generated for a datastore based measurement.
     * The measurementId makes the name unique per measurement.
     */
    public static buildRoleName(businessID: string, measurementId: string): string {
        return `${DATASTORE_ROLE_PREFIX}-${businessID}-${measurementId}`;
    }

    /**
     * Builds the S3 URI of a bucket/prefix combination belonging to a business
     */
    public static buildLocation(bucket: string, businessID: string): string {
        if (!bucket) {
            return undefined;
        }
        return businessID ? `s3://${bucket}/${businessID}` : `s3://${bucket}`;
    }

    /**
     * The trust policy of the generated role.
     * Only the customer account is allowed to assume the role and only when the generated external ID is presented
     */
    public static buildTrustPolicy(accountId: string, externalId: string) {
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'PaigoDatastoreMeasurementTrust',
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        };
    }

    /**
     * The access policy of the generated role.
     * The role can only deliver usage records to, and read records from, the prefixes owned by the business
     */
    public static buildAccessPolicy(businessID: string) {
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'PaigoDatastoreMeasurementIngestion',
                    Effect: 'Allow',
                    Action: ['s3:PutObject', 's3:GetObject'],
                    Resource: [`arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/*`],
                },
                {
                    Sid: 'PaigoDatastoreMeasurementDLQ',
                    Effect: 'Allow',
                    Action: ['s3:GetObject'],
                    Resource: [`arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/*`],
                },
            ],
        };
    }

    private static getIAMClient(region?: string): IAM {
        return new IAM({ region: region ? region : process.env.AWS_REGION || DEFAULT_DATASTORE_REGION });
    }

    private static isS3(datastoreAccessInformation: DatastoreAccessInformation): boolean {
        const { platform } = datastoreAccessInformation;
        return !platform || platform.toLowerCase() === SupportedDatastores.s3;
    }

    /**
     * Provisions everything a customer needs in order to deliver usage records to Paigo.
     * <br>
     * A dedicated, uniquely named, IAM role is created. The role is only assumable by the customer account
     * when the freshly generated external ID is presented, and it is scoped down to the ingestion and DLQ
     * prefixes owned by the business.
     */
    public static async setupAccess(dbAccessInformation: DatastoreAccessInformation) {
        if (!dbAccessInformation || !DatastoreAccessInformation.isS3(dbAccessInformation)) {
            return dbAccessInformation;
        }
        const { accountId, businessID, measurementId, region } = dbAccessInformation;
        const externalId = dbAccessInformation.externalId ? dbAccessInformation.externalId : randomUUID();
        const roleName = DatastoreAccessInformation.buildRoleName(businessID, measurementId);
        try {
            const iam = DatastoreAccessInformation.getIAMClient(region);
            const createdRole = await iam.createRole({
                RoleName: roleName,
                Description: `Paigo datastore based usage measurement role for businessID: ${businessID}`,
                AssumeRolePolicyDocument: JSON.stringify(
                    DatastoreAccessInformation.buildTrustPolicy(accountId, externalId)
                ),
                Tags: [
                    { Key: 'businessID', Value: `${businessID}` },
                    { Key: 'measurementId', Value: `${measurementId}` },
                ],
            });
            await iam.putRolePolicy({
                RoleName: roleName,
                PolicyName: roleName,
                PolicyDocument: JSON.stringify(DatastoreAccessInformation.buildAccessPolicy(businessID)),
            });
            dbAccessInformation.externalId = externalId;
            dbAccessInformation.iamRoleArn = createdRole?.Role?.Arn
                ? createdRole.Role.Arn
                : dbAccessInformation.iamRoleArn;
            dbAccessInformation.ingestion = DatastoreAccessInformation.buildLocation(
                process.env.DB_MEASUREMENT_BUCKET_NAME,
                businessID
            );
            dbAccessInformation.dlq = DatastoreAccessInformation.buildLocation(
                process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME,
                businessID
            );
            dbAccessInformation.region = region ? region : DEFAULT_DATASTORE_REGION;
            return dbAccessInformation;
        } catch (e) {
            throw DatastoreAccessInformation.mapError(e, accountId);
        }
    }

    /**
     * Updates the trust relationship of the already generated role so that the newly provided
     * account is the one allowed to assume it. The role itself and the external ID are preserved.
     */
    public static async updateAccess(dbAccessInformation: DatastoreAccessInformation) {
        if (!dbAccessInformation || !DatastoreAccessInformation.isS3(dbAccessInformation)) {
            return dbAccessInformation;
        }
        const { accountId, businessID, measurementId, region } = dbAccessInformation;
        const externalId = dbAccessInformation.externalId ? dbAccessInformation.externalId : randomUUID();
        const roleName = DatastoreAccessInformation.buildRoleName(businessID, measurementId);
        try {
            const iam = DatastoreAccessInformation.getIAMClient(region);
            await iam.updateAssumeRolePolicy({
                RoleName: roleName,
                PolicyDocument: JSON.stringify(
                    DatastoreAccessInformation.buildTrustPolicy(accountId, externalId)
                ),
            });
            dbAccessInformation.externalId = externalId;
            return dbAccessInformation;
        } catch (e) {
            throw DatastoreAccessInformation.mapError(e, accountId);
        }
    }

    private static mapError(e, accountId: string) {
        const code = e?.Code || e?.name || e?.code;
        if (code === 'MalformedPolicy' || code === 'MalformedPolicyDocument' || code === 'MalformedPolicyDocumentException') {
            return new BadRequestException(`AccountId: ${accountId} is invalid`);
        }
        return e;
    }
}

