import { Tag } from '@aws-sdk/client-ec2';
import { S3 } from '@aws-sdk/client-s3';
import { randomUUID } from 'crypto';
import EventEmitter from 'events';
import { AuditService } from '../../audit/audit.service';
import { AuditScope } from '../../audit/entities/audit.interface';
import { InfluxService } from '../../influx/influx.service';
import { MeasurementFormat } from './measurement.interface';

const eventEmitter = new EventEmitter();

/**
 * The suffix appended to the mirrored source key of every record published to the DLQ
 */
export const DLQ_KEY_SUFFIX = '.message.text';

/**
 * The shape of a failure which can be delivered to the DLQ.
 * Every field is optional so any producer can hand over as much context as it has.
 */
export interface DLQFailure {
    /**
     * The input which failed to be processed
     */
    input?: unknown;
    /**
     * The error which caused the failure
     */
    error?: unknown;
    /**
     * The key of the object the failed input originated from.
     * This can either be a relative key, `businessID/some/key.json`,
     * or a fully qualified one, `s3://some-bucket/businessID/some/key.json`
     */
    sourceKey?: string;
    /**
     * Alias of `sourceKey`, the key of the object the failed input originated from
     */
    s3Key?: string;
    /**
     * The bucket the failed input originated from
     */
    sourceBucket?: string;
    /**
     * A human readable description of the processor which failed
     */
    source?: string;
}

export class StandardMeasurementEntity implements MeasurementFormat {
    public timeStamp?: string;
    public dimensionId?: string;
    public businessID: string;
    public applicationId?: string;
    public serviceId?: string;
    public recordValue: number;
    public metadata: Record<string, string>;
    public _measurement: string;
    public static allowedTags = ['paigoApplicationId', 'paigoServiceId', 'paigoDimensionId'];

    constructor(measurement: MeasurementFormat) {
        if (measurement.timeStamp) {
            this.timeStamp = measurement.timeStamp;
        } else {
            this.timeStamp = new Date().toISOString();
        }
        this.dimensionId = measurement.dimensionId;
        this.applicationId = measurement.applicationId;
        this.serviceId = measurement.serviceId;
        this.recordValue = measurement.recordValue;
        this.metadata = measurement.metadata;
        this.businessID = measurement.businessID;
        this._measurement = measurement._measurement;
    }
    static publish(publishRequest: MeasurementFormat) {
        eventEmitter.emit('standardMeasurements', publishRequest);
        return {
            message: 'published',
            id: randomUUID(),
            data: [publishRequest],
        };
    }
    static subscribe(influxService: InfluxService) {
        eventEmitter.on('standardMeasurements', async (measurementFormat: MeasurementFormat) => {
            const point = MeasurementFormat.getPointForm(measurementFormat, influxService);
            try {
                await influxService.loadPoints(`${process.env.STAGE}-usage-data`, `paigo`, [point]);
            } catch (err) {
                AuditService.publishEvent({
                    data: [{ err }],
                    message: 'Failed to index Measurement',
                    topic: AuditScope.ERROR,
                });
            }
        });
    }
    static awsTagKeyReducer(Tags: Tag[]) {
        if (Tags) {
            return Tags.reduce((acc, { Key, Value }): any => {
                if (StandardMeasurementEntity.allowedTags.includes(Key)) {
                    acc[Key] = Value;
                }
                return acc;
            }, {});
        } else {
            return {};
        }
    }

    /**
     * Turns any source key into a key relative to its bucket.
     * Fully qualified keys, `s3://some-bucket/businessID/key` or `arn:aws:s3:::some-bucket/businessID/key`,
     * get the bucket stripped away, keys which are already relative are handed back untouched.
     */
    static toRelativeSourceKey(sourceKey: string, sourceBucket?: string): string {
        if (!sourceKey) {
            return sourceKey;
        }
        let relativeKey = `${sourceKey}`.trim();
        if (relativeKey.toLowerCase().startsWith('s3://')) {
            relativeKey =<REDACTED>
            relativeKey =<REDACTED>
        } else if (relativeKey.toLowerCase().startsWith('arn:aws:s3:::')) {
            relativeKey =<REDACTED>
            relativeKey =<REDACTED>
        } else if (sourceBucket && relativeKey.startsWith(`${sourceBucket}/`)) {
            relativeKey =<REDACTED>
        }
        while (relativeKey.startsWith('/')) {
            relativeKey =<REDACTED>
        }
        return relativeKey;
    }

    /**
     * The key a failure is delivered to inside of the DLQ.
     * The source key is mirrored so a failed record is always findable through the key it came in on.
     */
    static buildDLQKey(sourceKey: string, sourceBucket?: string): string {
        const relativeKey = StandardMeasurementEntity.toRelativeSourceKey(sourceKey, sourceBucket);
        if (!relativeKey) {
            return `unknown-source/${randomUUID()}${DLQ_KEY_SUFFIX}`;
        }
        return `${relativeKey}${DLQ_KEY_SUFFIX}`;
    }

    /**
     * Delivers an input which could not be processed to the configured DLQ.
     * <br>
     * The failure is written under the mirrored source key so it can be correlated with the object it came
     * in on, and it holds the failed input alongside the metadata of the failed processing attempt.
     *
     * @param failure either a failure descriptor, or the input which failed to be processed
     * @param sourceKey the key of the object the failed input originated from
     * @param error the error which caused the failure
     */
    static async publishFailureToDLQ(failure: DLQFailure | unknown, sourceKey?: string | unknown, error?: unknown) {
        const normalized = StandardMeasurementEntity.normalizeFailure(failure, sourceKey, error);
        const sourceBucket = normalized.sourceBucket ? normalized.sourceBucket : process.env.DB_MEASUREMENT_BUCKET_NAME;
        const Bucket = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
        const Key = StandardMeasurementEntity.buildDLQKey(normalized.sourceKey, sourceBucket);
        const failureRecord = {
            input: normalized.input,
            message: normalized.input && typeof normalized.input === 'object' ? normalized.input['message'] : undefined,
            error: StandardMeasurementEntity.errorToString(normalized.error),
            errorType: normalized.error?.['name'],
            s3Key: normalized.sourceKey,
            sourceKey: StandardMeasurementEntity.toRelativeSourceKey(normalized.sourceKey, sourceBucket),
            sourceBucket,
            dlqBucket: Bucket,
            dlqKey: Key,
            processedAt: new Date().toISOString(),
            processor: normalized.source ? normalized.source : StandardMeasurementEntity.name,
        };
        const Body = JSON.stringify(failureRecord);
        try {
            const s3 = new S3({ region: process.env.AWS_REGION });
            await s3.putObject({
                Bucket,
                Key,
                Body,
                ContentType: 'text/plain',
            });
            return { message: 'Published failure to DLQ', bucket: Bucket, key: Key };
        } catch (err) {
            AuditService.publishEvent({
                data: [{ err, bucket: Bucket, key: Key }],
                message: 'Failed to publish failure to DLQ',
                topic: AuditScope.ERROR,
            });
            throw err;
        }
    }

    private static normalizeFailure(
        failure: DLQFailure | unknown,
        sourceKey?: string | unknown,
        error?: unknown
    ): DLQFailure {
        const descriptor = (failure ? failure : {}) as DLQFailure;
        const isDescriptor =
            failure &&
            typeof failure === 'object' &&
            ('input' in descriptor || 'error' in descriptor || 'sourceKey' in descriptor);
        if (isDescriptor) {
            return {
                input: 'input' in descriptor ? descriptor.input : failure,
                error: descriptor.error !== undefined ? descriptor.error : error,
                sourceKey: descriptor.sourceKey ? descriptor.sourceKey : descriptor.s3Key,
                sourceBucket: descriptor.sourceBucket,
                source: descriptor.source,
            };
        }
        return {
            input: failure,
            error: typeof sourceKey === 'string' ? error : sourceKey !== undefined ? sourceKey : error,
            sourceKey: typeof sourceKey === 'string' ? sourceKey : descriptor.s3Key,
            sourceBucket: descriptor.sourceBucket,
            source: descriptor.source,
        };
    }

    private static errorToString(error: unknown): string {
        if (error === undefined || error === null) {
            return undefined;
        }
        if (error instanceof Error) {
            return error.message;
        }
        if (typeof error === 'string') {
            return error;
        }
        try {
            return JSON.stringify(error);
        } catch (e) {
            return `${error}`;
        }
    }
}

