import { CreateRoleCommand, IAMClient, PutRolePolicyCommand, UpdateAssumeRolePolicyCommand } from '@aws-sdk/client-iam';
import { mockClient } from 'aws-sdk-client-mock';
import {
    DatastoreAccessInformation,
    DEFAULT_DATASTORE_REGION,
    SupportedDatastores,
} from './measurement-config.entity';

describe('DatastoreAccessInformation', () => {
    const iamMock = mockClient(IAMClient);
    const businessID = 'fakeBusiness';
    const measurementId = 'fake-measurement-id';
    const accountId = '623673123435';
    const generatedRoleArn = `arn:aws:iam::214826386939:role/datastore-${businessID}-${measurementId}`;

    beforeEach(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'paigo-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'paigo-usage-record-dlq-bucket';
        process.env.AWS_REGION = 'us-east-1';
        iamMock.reset();
        iamMock.on(CreateRoleCommand).resolves({ Role: { Arn: generatedRoleArn } as never });
        iamMock.on(PutRolePolicyCommand).resolves({});
        iamMock.on(UpdateAssumeRolePolicyCommand).resolves({});
    });

    it('defaults the platform to s3 and the region to us-east-1', () => {
        const configuration = new DatastoreAccessInformation({ accountId, businessID } as DatastoreAccessInformation);

        expect(configuration.platform).toEqual(SupportedDatastores.s3);
        expect(configuration.region).toEqual(DEFAULT_DATASTORE_REGION);
        expect(configuration.accountId).toEqual(accountId);
    });

    it('provisions a uniquely named role trusting the customer account with a fresh external id', async () => {
        const configuration = await DatastoreAccessInformation.setupAccess(
            new DatastoreAccessInformation({
                accountId,
                businessID,
                measurementId,
            } as DatastoreAccessInformation)
        );

        const [createRoleCall] = iamMock.commandCalls(CreateRoleCommand);
        const { RoleName, AssumeRolePolicyDocument } = createRoleCall.args[0].input;

        expect(RoleName).toEqual(`datastore-${businessID}-${measurementId}`);
        const trustPolicy = JSON.parse(AssumeRolePolicyDocument);
        expect(trustPolicy.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${accountId}:root`);
        expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(configuration.externalId);
        expect(configuration.externalId).toBeTruthy();
        expect(configuration.iamRoleArn).toEqual(generatedRoleArn);
        expect(configuration.ingestion).toEqual(
            `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}`
        );
        expect(configuration.dlq).toEqual(`s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}`);
        expect(configuration.region).toEqual(DEFAULT_DATASTORE_REGION);
    });

    it('scopes the generated policy to the ingestion and dlq prefixes of the business', async () => {
        await DatastoreAccessInformation.setupAccess(
            new DatastoreAccessInformation({
                accountId,
                businessID,
                measurementId,
            } as DatastoreAccessInformation)
        );

        const [putRolePolicyCall] = iamMock.commandCalls(PutRolePolicyCommand);
        const { RoleName, PolicyName, PolicyDocument } = putRolePolicyCall.args[0].input;
        expect(RoleName).toEqual(`datastore-${businessID}-${measurementId}`);
        expect(PolicyName).toContain(`datastore-${businessID}-${measurementId}`);
        expect(PolicyDocument).toContain(`arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/*`);
        expect(PolicyDocument).toContain(`arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/*`);
    });

    it('generates a different external id and role name for every measurement', async () => {
        const first = await DatastoreAccessInformation.setupAccess(
            new DatastoreAccessInformation({ accountId, businessID, measurementId } as DatastoreAccessInformation)
        );
        const second = await DatastoreAccessInformation.setupAccess(
            new DatastoreAccessInformation({
                accountId,
                businessID,
                measurementId: 'another-measurement-id',
            } as DatastoreAccessInformation)
        );

        expect(first.externalId).not.toEqual(second.externalId);
        const [firstCall, secondCall] = iamMock.commandCalls(CreateRoleCommand);
        expect(firstCall.args[0].input.RoleName).not.toEqual(secondCall.args[0].input.RoleName);
    });

    it('updates the trust of the role while preserving the role and the external id', async () => {
        const externalId = 'already-generated-external-id';
        const updatedAccountId = '999999999999';

        const configuration = await DatastoreAccessInformation.updateAccess(
            new DatastoreAccessInformation({
                accountId: updatedAccountId,
                businessID,
                measurementId,
                externalId,
                iamRoleArn: generatedRoleArn,
            } as DatastoreAccessInformation)
        );

        expect(iamMock.commandCalls(CreateRoleCommand)).toHaveLength(0);
        const [updateCall] = iamMock.commandCalls(UpdateAssumeRolePolicyCommand);
        const { RoleName, PolicyDocument } = updateCall.args[0].input;
        expect(RoleName).toEqual(`datastore-${businessID}-${measurementId}`);
        const trustPolicy = JSON.parse(PolicyDocument);
        expect(trustPolicy.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${updatedAccountId}:root`);
        expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(externalId);
        expect(configuration.externalId).toEqual(externalId);
        expect(configuration.iamRoleArn).toEqual(generatedRoleArn);
    });
});

