/**
 * A small compatibility layer over the AWS SDK v3 clients.
 *
 * The SDK ships two flavours of every client: the aggregated client, which exposes one method per
 * operation (`s3.putObject(input)`), and the bare client, which is driven with commands
 * (`s3Client.send(new PutObjectCommand(input))`). Both flavours are supported here so callers do not
 * have to care about which flavour of a client they got handed.
 */

/**
 * A logger which does nothing. The SDK falls back to its own internal no-op logger when none is
 * provided, which is only available on matching client/smithy versions, so one is always provided.
 */
const noOpLogger = {
    trace: () => undefined,
    debug: () => undefined,
    info: () => undefined,
    warn: () => undefined,
    error: () => undefined,
};

/**
 * Builds the first constructable AWS client of the provided constructors.
 *
 * @param constructors the client constructors to try, in order of preference
 * @param config the client configuration
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const buildAwsClient = (constructors: any[], config: Record<string, unknown> = {}): any => {
    let firstError;
    for (const AwsClient of constructors) {
        if (typeof AwsClient !== 'function') {
            continue;
        }
        try {
            return new AwsClient({ logger: noOpLogger, ...config });
        } catch (e) {
            firstError = firstError ? firstError : e;
        }
    }
    throw firstError ? firstError : new Error('Unable to build an AWS client');
};

/**
 * Runs one AWS operation against a client, no matter the flavour of the client.
 *
 * @param client the AWS client to run the operation with
 * @param operation the name of the operation on the aggregated client, for example `createRole`
 * @param AwsCommand the command implementing the operation, for example `CreateRoleCommand`
 * @param input the input of the operation
 */
export const runAwsOperation = async <Input, Output>(
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    client: any,
    operation: string,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    AwsCommand: any,
    input: Input
): Promise<Output> => {
    if (client && typeof client[operation] === 'function') {
        return client[operation](input);
    }
    if (client && typeof client.send === 'function' && typeof AwsCommand === 'function') {
        return client.send(new AwsCommand(input));
    }
    throw new Error(`Unable to run the AWS operation: ${operation}`);
};

