/**
 * A small compatibility layer over the AWS SDK v3 clients.
 *
 * Every service in the SDK ships two flavours of client: the aggregated client, which exposes one
 * method per operation (`s3.putObject(input)`), and the bare client, which is driven with commands
 * (`s3Client.send(new PutObjectCommand(input))`). Both flavours behave identically, and which one is
 * available depends on the version of the client that is installed, so this helper simply runs an
 * operation against the first flavour which is able to produce a result.
 */

/**
 * A logger which does nothing. The SDK falls back to its own internal no-op logger when none is
 * provided, which is only available when the client and the shared smithy runtime versions match, so
 * one is always provided here.
 */
const noOpLogger = {
    trace: () => undefined,
    debug: () => undefined,
    info: () => undefined,
    warn: () => undefined,
    error: () => undefined,
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type AwsClientConstructor = any;

export class AwsClientAdapter {
    private readonly constructors: AwsClientConstructor[];
    private readonly config: Record<string, unknown>;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    private clients: any[];

    constructor(constructors: AwsClientConstructor[], config: Record<string, unknown> = {}) {
        this.constructors = constructors;
        this.config = config;
    }

    /**
     * Runs one AWS operation, no matter which flavour of client is available.
     *
     * @param operation the name of the operation on the aggregated client, for example `createRole`
     * @param AwsCommand the command implementing the operation, for example `CreateRoleCommand`
     * @param input the input of the operation
     */
    async run<Input, Output>(operation: string, AwsCommand: AwsClientConstructor, input: Input): Promise<Output> {
        let output;
        for (const client of this.getClients()) {
            if (typeof client[operation] === 'function') {
                output = await client[operation](input);
            } else if (typeof client.send === 'function' && typeof AwsCommand === 'function') {
                output = await client.send(new AwsCommand(input));
            } else {
                continue;
            }
            if (output !== undefined && output !== null) {
                return output;
            }
        }
        return output;
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    private getClients(): any[] {
        if (!this.clients) {
            this.clients = this.constructors
                .filter((AwsClient) => typeof AwsClient === 'function')
                .map((AwsClient) => {
                    try {
                        return new AwsClient({ logger: noOpLogger, ...this.config });
                    } catch (e) {
                        return undefined;
                    }
                })
                .filter((client) => client);
            if (!this.clients.length) {
                throw new Error('Unable to build an AWS client');
            }
        }
        return this.clients;
    }
}

/**
 * Builds an adapter around the provided AWS client constructors, listed in order of preference.
 */
export const buildAwsClient = (constructors: AwsClientConstructor[], config: Record<string, unknown> = {}) =>
    new AwsClientAdapter(constructors, config);

