import { PutObjectCommand, S3 } from '@aws-sdk/client-s3';
import { mockClient } from 'aws-sdk-client-mock';
import { DLQ_KEY_SUFFIX, StandardMeasurementEntity } from './standardMeasurement.entity';

describe('StandardMeasurementEntity DLQ', () => {
    const s3Mock = mockClient(S3);
    const relativeSourceKey = 'fakeBusiness/2023/02/08/usage-record.json';

    beforeEach(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'paigo-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'paigo-usage-record-dlq-bucket';
        process.env.AWS_REGION = 'us-east-1';
        s3Mock.reset();
        s3Mock.on(PutObjectCommand).resolves({});
    });

    it('publishes the failed input and the processing metadata under the mirrored source key', async () => {
        const input = { message: 'not a json record', s3Key: relativeSourceKey };
        const error = new Error('Unexpected token o in JSON');

        await StandardMeasurementEntity.publishFailureToDLQ({ input, error, sourceKey: relativeSourceKey });

        const [putCall] = s3Mock.commandCalls(PutObjectCommand);
        const { Bucket, Key, Body } = putCall.args[0].input;
        expect(Bucket).toEqual(process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME);
        expect(Key).toEqual(`${relativeSourceKey}${DLQ_KEY_SUFFIX}`);
        const published = JSON.parse(`${Body}`);
        expect(published.input).toEqual(input);
        expect(published.error).toEqual('Unexpected token o in JSON');
        expect(published.sourceKey).toEqual(relativeSourceKey);
        expect(published.processedAt).toBeTruthy();
    });

    it('mirrors fully qualified source keys relative to their bucket', async () => {
        await StandardMeasurementEntity.publishFailureToDLQ({
            input: { message: 'broken' },
            error: new Error('broken'),
            sourceKey: `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${relativeSourceKey}`,
        });

        const [putCall] = s3Mock.commandCalls(PutObjectCommand);
        expect(putCall.args[0].input.Key).toEqual(`${relativeSourceKey}${DLQ_KEY_SUFFIX}`);
    });

    it('mirrors source keys which are already relative', () => {
        expect(StandardMeasurementEntity.toRelativeSourceKey(relativeSourceKey)).toEqual(relativeSourceKey);
        expect(
            StandardMeasurementEntity.toRelativeSourceKey(
                `${process.env.DB_MEASUREMENT_BUCKET_NAME}/${relativeSourceKey}`,
                process.env.DB_MEASUREMENT_BUCKET_NAME
            )
        ).toEqual(relativeSourceKey);
    });
});

