import { DimensionsService } from '../dimensions/dimensions.service';

describe('MeasurementConfigService datastore based measurements', () => {
    const iamMock = mockClient(IAMClient);
    const businessID = 'fakeBusiness';
    const accountId = '623673123435';
    const fakeSubject = 'fakeSubject';
    const roleArn = 'arn:aws:iam::214826386939:role/generated-datastore-role';
    const mockLoadPoints = jest.fn();
    const mockTag = jest.fn();
    const mockReadMeasurementConfigData = jest.fn();
    let service: MeasurementConfigService;

    beforeEach(async () => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'paigo-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'paigo-usage-record-dlq-bucket';
        process.env.AWS_REGION = 'us-east-1';
        iamMock.reset();
        iamMock.on(CreateRoleCommand).resolves({ Role: { Arn: roleArn } as never });
        iamMock.on(PutRolePolicyCommand).resolves({});
        iamMock.on(UpdateAssumeRolePolicyCommand).resolves({});

        const module: TestingModule = await Test.createTestingModule({
            providers: [MeasurementConfigService],
            imports: [],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return {
                        loadPoints: mockLoadPoints,
                        getPoint: () => ({ tag: mockTag, stringField: jest.fn() }),
                        readMeasurementConfigData: mockReadMeasurementConfigData,
                        readMeasurementConfigDataByDimensionId: () => [],
                    };
                }
                if (token === SchedulerService) {
                    return { create: jest.fn() };
                }
                if (token === DimensionsService) {
                    return { transformDtoToEntityInput: jest.fn(), findOneByDimensionId: jest.fn() };
                }
            })
            .compile();

        service = module.get<MeasurementConfigService>(MeasurementConfigService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('provisions and persists the generated access information of a datastore based measurement', async () => {
        const { measurementId, measurementConfiguration } = await service.create(
            {
                measurementMode: measurementMode.datastoreBased,
                measurementConfiguration: { platform: SupportedDatastores.s3, accountId } as DatastoreAccessInformation,
                businessID,
            },
            fakeSubject
        );

        const [createRoleCall] = iamMock.commandCalls(CreateRoleCommand);
        expect(createRoleCall.args[0].input.RoleName).toEqual(`datastore-${businessID}-${measurementId}`);

        const configuration = measurementConfiguration as DatastoreAccessInformation;
        expect(configuration.platform).toEqual(SupportedDatastores.s3);
        expect(configuration.accountId).toEqual(accountId);
        expect(configuration.iamRoleArn).toEqual(roleArn);
        expect(configuration.externalId).toBeTruthy();
        expect(configuration.ingestion).toEqual(`s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}`);
        expect(configuration.dlq).toEqual(`s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}`);
        expect(configuration.region).toEqual('us-east-1');

        // The generated access information is persisted alongside the measurement
        expect(mockLoadPoints).toHaveBeenCalled();
        expect(mockTag).toHaveBeenCalledWith('iamRoleArn', roleArn);
        expect(mockTag).toHaveBeenCalledWith('externalId', configuration.externalId);
        expect(mockTag).toHaveBeenCalledWith('accountId', accountId);
        expect(mockTag).toHaveBeenCalledWith('platform', SupportedDatastores.s3);
        expect(mockTag).toHaveBeenCalledWith('ingestion', configuration.ingestion);
        expect(mockTag).toHaveBeenCalledWith('dlq', configuration.dlq);
        expect(mockTag).toHaveBeenCalledWith('region', 'us-east-1');
    });

    it('updates the trust of the generated role when the account changes', async () => {
        const measurementId = 'fake-measurement-id';
        const externalId = 'already-generated-external-id';
        mockReadMeasurementConfigData.mockResolvedValue([
            {
                measurementId,
                _value: measurementMode.datastoreBased,
                businessID,
                measurementName: 'datastore measurement',
                subject: fakeSubject,
                platform: SupportedDatastores.s3,
                accountId,
                iamRoleArn: roleArn,
                externalId,
                ingestion: `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}`,
                dlq: `s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}`,
                region: 'us-east-1',
            },
        ]);
        const updatedAccountId = '999999999999';

        const { measurementConfiguration } = await service.update(
            {
                measurementId,
                businessID,
                measurementName: undefined,
                measurementConfiguration: { accountId: updatedAccountId },
            },
            fakeSubject
        );

        const [updateCall] = iamMock.commandCalls(UpdateAssumeRolePolicyCommand);
        expect(updateCall.args[0].input.RoleName).toEqual(`datastore-${businessID}-${measurementId}`);
        const trustPolicy = JSON.parse(updateCall.args[0].input.PolicyDocument);
        expect(trustPolicy.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${updatedAccountId}:root`);
        expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(externalId);

        const configuration = measurementConfiguration as DatastoreAccessInformation;
        expect(configuration.accountId).toEqual(updatedAccountId);
        expect(configuration.iamRoleArn).toEqual(roleArn);
        expect(configuration.externalId).toEqual(externalId);
        expect(iamMock.commandCalls(CreateRoleCommand)).toHaveLength(0);
    });
});

