/**
 * Parses one standard usage record. Anything which can not be parsed, or which does not hold a
 * single standard usage record, is malformed and belongs in the DLQ.
 */
private static parseRecord(message: unknown) {
    const parsed = typeof message === 'string' ? JSON.parse(message) : message;
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        throw new Error('The usage record is not a single standard usage record');
    }
    const isStandardUsageRecord = ['recordValue', 'dimensionId', 'serviceId', 'applicationId', 'timeStamp'].some(
        (field) => parsed[field] !== undefined
    );
    if (!isStandardUsageRecord) {
        throw new Error('The usage record does not hold any standard usage record field');
    }
    return parsed;
}

arguments.oldString:
/**
 * Parses one standard usage record. Anything which is not a standard usage record is malformed.
 */
private static parseRecord(message: unknown) {
    const parsed = typeof message === 'string' ? JSON.parse(message) : message;
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        throw new Error('Usage record is not a standard usage record');
    }
    const { recordValue, dimensionId, serviceId, applicationId } = parsed;
    if (recordValue === undefined || recordValue === null) {
        throw new Error('Usage record is missing a recordValue');
    }
    if (!dimensionId && !serviceId && !applicationId) {
        throw new Error('Usage record is missing a dimensionId, serviceId and applicationId');
    }
    return parsed;
}

