/**
 * Accepts either a failure descriptor, `{ input, error, sourceKey }`, or the failed input followed
 * by the source key and the error, and normalizes both into a failure descriptor.
 */
private static normalizeFailure(
    failure: DLQFailure | unknown,
    sourceKey?: string | unknown,
    error?: unknown
): DLQFailure {
    const descriptor = (failure ? failure : {}) as DLQFailure;
    const isDescriptor =
        !!failure &&
        typeof failure === 'object' &&
        ('input' in descriptor || 'error' in descriptor || 'sourceKey' in descriptor);
    const input = isDescriptor ? descriptor.input : failure;
    const inputSourceKey = input && typeof input === 'object' ? input['s3Key'] : undefined;
    const positionalError = typeof sourceKey === 'string' || sourceKey === undefined ? error : sourceKey;
    const positionalSourceKey = typeof sourceKey === 'string' ? sourceKey : undefined;
    return {
        input,
        error: isDescriptor && descriptor.error !== undefined ? descriptor.error : positionalError,
        sourceKey: positionalSourceKey
            ? positionalSourceKey
            : descriptor.sourceKey
            ? descriptor.sourceKey
            : descriptor.s3Key
            ? descriptor.s3Key
            : inputSourceKey,
        sourceBucket: descriptor.sourceBucket,
        source: descriptor.source,
    };
}

