    return {
        input: failure,
        error: typeof sourceKey === 'string' ? error : sourceKey !== undefined ? sourceKey : error,
        sourceKey: typeof sourceKey === 'string' ? sourceKey : descriptor.s3Key,
        sourceBucket: descriptor.sourceBucket,
        source: descriptor.source,
